345	    /**
346	     * Counts the existing owners who, before this create, already share the given first and last name.
347	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
348	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
349	     * case or spacing still count as the same name.
350	     *
351	     * @param firstName the first name of the owner being created
352	     * @param lastName the last name of the owner being created
353	     * @return the number of existing owners sharing both names (zero when none)
354	     */
355	    private int countNamesakes(String firstName, String lastName) {
356	        String first = normalizeHouseholdField(firstName);
357	        String last = normalizeHouseholdField(lastName);
358	        return (int) this.clinicService.findAllOwners().stream()
359	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
360	                && normalizeHouseholdField(existing.getLastName()).equals(last))
361	            .count();
362	    }
363	
364	    /**
365	     * Rejects an owner create whose city already holds the maximum number of owners. Owners are
366	     * grouped into a city case-insensitively after surrounding whitespace is trimmed and internal
367	     * runs are collapsed (mirroring the other city comparisons), so cosmetic differences in case or
368	     * spacing count as the same city. When the city already contains {@link #MAX_OWNERS_PER_CITY} or
369	     * more owners the create is rejected as a conflict.
370	     *
371	     * @param city the city of the owner being created
372	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
373	     */
374	    /**
375	     * Rejects an owner create once the maximum number of owners have already been registered on the
376	     * business day this owner would land on. Owners are grouped by their {@code registrationDate},
377	     * which is always a business day (a weekend effective date is rolled forward to the following
378	     * Monday); when {@link #MAX_OWNERS_PER_DAY} or more existing owners already carry the given
379	     * business day the create is rejected as too many requests. Because a weekend effective date is
380	     * rolled forward, this quota bounds the number of owners that may be registered per business day.
381	     *
382	     * @param businessDay the adjusted business day the owner being created would be registered on
383	     * @throws OwnerDailyLimitExceededException if the business day already holds the maximum number of owners
384	     */
385	    private void rejectDailyLimitExceeded(LocalDate businessDay) {
386	        long ownersOnDay = this.clinicService.findAllOwners().stream()
387	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
388	            .count();
389	        if (ownersOnDay >= MAX_OWNERS_PER_DAY) {
390	            throw new OwnerDailyLimitExceededException(businessDay, MAX_OWNERS_PER_DAY);
391	        }
392	    }
393	
394	    /**
395	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is moved
396	     * forward to the following Monday; a weekday is returned unchanged. This applies whether the date
397	     * was supplied on the request or defaulted to the server's current date.
398	     *
399	     * @param date the effective registration date (supplied or defaulted)
400	     * @return the same date when it is a weekday, otherwise the following Monday
401	     */
402	    /**
403	     * Reports whether responses should carry a bulk-signup warning. The warning is active once more
404	     * than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry today's business-day
405	     * registration date (the same accumulation basis as the per-day create limit), signalling that the
406	     * daily create volume is approaching {@link #MAX_OWNERS_PER_DAY}.
407	     *
408	     * @return {@code true} when more than the threshold number of owners are already registered on
409	     *         today's business day, otherwise {@code false}
410	     */
411	    private boolean isBulkSignupWarningActive() {
412	        LocalDate today = toBusinessDay(LocalDate.now());
413	        long ownersToday = this.clinicService.findAllOwners().stream()
414	            .filter(existing -> today.equals(existing.getRegistrationDate()))
415	            .count();
416	        return ownersToday > BULK_SIGNUP_WARNING_THRESHOLD;
417	    }
418	
419	    private LocalDate toBusinessDay(LocalDate date) {
420	        return switch (date.getDayOfWeek()) {
421	            case SATURDAY -> date.plusDays(2);
422	            case SUNDAY -> date.plusDays(1);
423	            default -> date;
424	        };
425	    }
426	
427	    private void rejectCityAtCapacity(String city) {
428	        String normalizedCity = normalizeHouseholdField(city);
429	        long ownersInCity = this.clinicService.findAllOwners().stream()
430	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
431	            .count();
432	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
433	            throw new OwnerCityCapacityExceededException(city, MAX_OWNERS_PER_CITY);
434	        }
435	    }
436	
437	    /**
438	     * Builds an owner's customer code, formatted '&lt;REGION&gt;-&lt;HASH8&gt;'. REGION is the region
439	     * code derived from the owner's postcode (falling back to their city; see {@link LocalityLookup}),
440	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over the owner's
441	     * normalized telephone concatenated with their last name (e.g. 'NSW-1A2B3C4D'). The code carries no
442	     * sequence number; two owners resolve to the same code only when they share a region and produce the
443	     * same telephone-and-last-name hash.
444	     *
445	     * @param postcode the owner's postcode, used first to derive the region
446	     * @param city the owner's city, used to derive the region when the postcode maps to none
447	     * @param normalizedTelephone the owner's normalized (E.164) telephone
448	     * @param lastName the owner's last name
449	     * @return the formatted customer code
450	     */
451	    private String generateCustomerCode(String postcode, String city, String normalizedTelephone, String lastName) {
452	        String region = LocalityLookup.forPostcodeAndCity(postcode, city);
453	        String hash8 = sha256UpperHex(normalizedTelephone + lastName, 8);
454	        return region + "-" + hash8;
455	    }
456	
457	    /**
458	     * Builds an owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where
459	     * customerCode is the owner's customer code and YY is the last two digits of the
460	     * registrationDate year (e.g. 'NSW-1A2B3C4D-M26').
461	     *
462	     * @param customerCode the owner's customer code
463	     * @param registrationDate the owner's registration date
464	     * @return the formatted membership number
465	     */
466	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
467	        String yy = String.format("%02d", registrationDate.getYear() % 100);
468	        return customerCode + "-M" + yy;
469	    }
470	
471	    /**
472	     * The exact number of national (subscriber) digits an E.164 telephone must carry for a given
473	     * country calling code. Australia ('+61') uses 9 national digits and the North American
474	     * Numbering Plan ('+1') uses 10. Country codes not listed here are only bound by the generic
475	     * E.164 length (8 to 15 digits overall).
476	     */
477	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
478	        java.util.Map.of("61", 9, "1", 10);
